+public class ByteEmbedding extends Embedding<ByteEmbedding.ByteArrayWrapper> {
+
+    public static ByteEmbedding of(List<Byte> embedding) {
+        byte[] embeddingBytes = new byte[embedding.size()];
+        for (int i = 0; i < embedding.size(); i++) {
+            embeddingBytes[i] = embedding.get(i);
+        }
+        return new ByteEmbedding(embeddingBytes);
+    }
+
+    /**
+     * Wrapper so around a primitive byte array so that it can be
+     * treated as a generic
+     */
+    public static class ByteArrayWrapper implements EmbeddingValues {
+
+        final byte[] bytes;
+
+        public ByteArrayWrapper(byte[] bytes) {
+            this.bytes = bytes;
+        }
+
+        @Override
+        public XContentBuilder toXContent(XContentBuilder builder, Params params) throws IOException {
+            return valuesToXContent(EMBEDDING, builder, params);
+        }
+
+        @Override
+        public int size() {
+            return bytes.length;
+        }
+
+        @Override
+        public XContentBuilder valuesToXContent(String fieldName, XContentBuilder builder, Params params) throws IOException {
+            builder.startArray(fieldName);
+            for (var value : bytes) {
+                builder.value(value);
+            }
+            builder.endArray();
+            return builder;
+        }
+
+        @Override
+        public boolean equals(Object o) {
+            if (this == o) return true;
+            if (o == null || getClass() != o.getClass()) return false;
+            ByteArrayWrapper that = (ByteArrayWrapper) o;
+            return Arrays.equals(bytes, that.bytes);
+        }
+
+        @Override
+        public int hashCode() {
+            return Arrays.hashCode(bytes);
+        }
+    }
+
+    public ByteEmbedding(StreamInput in) throws IOException {
+        this(in.readByteArray());
+    }
+
+    public ByteEmbedding(byte[] embedding) {
+        super(new ByteArrayWrapper(embedding));
+    }
+
+    @Override
+    public void writeTo(StreamOutput out) throws IOException {
+        out.writeByteArray(embedding.bytes);
+    }
+
+    public byte[] bytes() {
+        return embedding.bytes;
+    }
+
+    public float[] toFloatArray() {
+        float[] floatArray = new float[embedding.bytes.length];
+        for (int i = 0; i < embedding.bytes.length; i++) {
+            floatArray[i] = ((Byte) embedding.bytes[i]).floatValue();
+        }
+        return floatArray;
+    }
+}
