+
+    public float[] asFloatArray() {
+        return embedding.floats;
+    }
+
+    public double[] asDoubleArray() {
+        var result = new double[embedding.floats.length];
+        for (int i = 0; i < embedding.floats.length; i++) {
+            result[i] = embedding.floats[i];
+        }
+        return result;
+    }
