+        try {
+            for (int b = 0; b < numBlocks; b++) {
+                blocks[b] = in.readNamedWriteable(Block.class);
+            }
+            CompositeBlock result = new CompositeBlock(blocks);
+            success = true;
+            return result;
+        } finally {
+            if (success == false) {
+                Releasables.close(blocks);
+            }
+        }
+    }
