+        );
+        assertThat(((ElasticsearchStatusException) exception.getCause()).status(), is(RestStatus.TOO_MANY_REQUESTS));
+    }
+
+    public void testCheckForFailureStatusCode_ThrowsFor404_ShouldNotRetry() {
